90	function failEvalRun(
91	  message: string,
92	  isCliInvocation: boolean,
93	  options: { logForCli?: () => void; cliFallback?: Eval } = {},
94	): Eval {
95	  if (isCliInvocation) {
96	    (options.logForCli ?? (() => logger.error(chalk.red(message))))();
97	    process.exitCode = 1;
98	    // Preserve a real Eval (e.g. a just-completed run flagged for a follow-up
99	    // failure like watch-mode setup) so downstream summaries don't misreport.
100	    return options.cliFallback ?? new Eval({}, { persisted: false });
101	  }
102	
103	  throw new EvalRunError(message);
104	}
